const RECOVERY_GUIDE = {"source": "The source of truth for the board's CLI recovery guide. observability/tests/recovery.test.ts pins its mode labels and writes every command to the Rust parser test files.", "modeLabels": {"requires-bot": "REST \u2014 requires the running bot", "direct-db": "direct DB \u2014 stop the bot / ensure it is not driving this id"}, "groups": [{"object": "transfer", "commands": [{"command": "st0x-liquidity-client --env production debug recheck <mint|redemption|usdc> <id>", "description": "Re-poll the provider and complete the transfer if it has settled.", "whenToUse": "A transfer is stuck or failed but the provider may have settled it.", "appliesTo": "Equity mint / redemption (any non-completed state), failed Base to Alpaca USDC deposit with an onchain deposit transaction. A failed Alpaca to Base deposit needs manual settlement, then reconcile-usdc.", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug resume", "description": "Re-drive ALL interrupted mints and redemptions (no id; best-effort per transfer, failures reported as counts).", "whenToUse": "Equity transfers were interrupted mid-flight and need re-driving via the bot.", "appliesTo": "All in-flight equity transfers", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug resume-usdc <alpaca-to-base|base-to-alpaca> <id>", "description": "Re-drive a single USDC bridge on the bot's transfer worker.", "whenToUse": "A USDC bridge stopped mid-flight, before or after the burn. For an Alpaca to Base bridge at converting, first confirm at Alpaca that no USD to USDC order for the transfer is still open: the resume can fail it without asking Alpaca (see its transfer dialog).", "appliesTo": "USDC bridge (in-flight)", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug fail-equity-transfer <mint|redemption> <id> --reason \"<reason>\"", "description": "Force a stuck transfer into the terminal Failed state.",